// renameReferences carries a renamed key over to every field of another table that refers
// to it (Rename). References from company tables are updated in this company — in
// every company when this table is global. Runs on the record's executor, so inside the
// caller's transaction.
func (t *CountryRegion) renameReferences(field string, oldValue, newValue interface{}) error {
	type reference struct {
		table      string
		global     bool
		column     string
		condColumn string // a conditional relation: only rows whose condColumn = condValue
		condValue  int
	}
	references := map[string][]reference{
		"code": {{"Bank_Account", false, "country_code", "", 0}, {"Company_Information", false, "country_code", "", 0}, {"Customer", false, "country_code", "", 0}, {"Customer_Bank_Account", false, "country_code", "", 0}, {"Finance_Charge_Memo_Header", false, "country_code", "", 0}, {"Intrastat_Jnl_Line", false, "country_code", "", 0}, {"Intrastat_Jnl_Line", false, "country_of_origin_code", "", 0}, {"Issued_Fin_Charge_Memo_Header", false, "country_code", "", 0}, {"Issued_Reminder_Header", false, "country_code", "", 0}, {"Item", false, "country_purchased_code", "", 0}, {"Item", false, "country_of_origin_code", "", 0}, {"Item_Journal_Line", false, "country_code", "", 0}, {"Item_Ledger_Entry", false, "country_code", "", 0}, {"Order_Address", false, "country_code", "", 0}, {"Project_Journal_Line", false, "country_code", "", 0}, {"Project_Ledger_Entry", false, "country_code", "", 0}, {"Purch_Cr_Memo_Hdr", false, "pay_to_country_code", "", 0}, {"Purch_Cr_Memo_Hdr", false, "buy_from_country_code", "", 0}, {"Purch_Cr_Memo_Hdr", false, "ship_to_country_code", "", 0}, {"Purch_Inv_Header", false, "pay_to_country_code", "", 0}, {"Purch_Inv_Header", false, "buy_from_country_code", "", 0}, {"Purch_Inv_Header", false, "ship_to_country_code", "", 0}, {"Purch_Rcpt_Header", false, "pay_to_country_code", "", 0}, {"Purch_Rcpt_Header", false, "buy_from_country_code", "", 0}, {"Purch_Rcpt_Header", false, "ship_to_country_code", "", 0}, {"Purchase_Header", false, "vat_country_code", "", 0}, {"Purchase_Header", false, "pay_to_country_code", "", 0}, {"Purchase_Header", false, "buy_from_country_code", "", 0}, {"Purchase_Header", false, "ship_to_country_code", "", 0}, {"Reminder_Header", false, "country_code", "", 0}, {"Sales_Cr_Memo_Header", false, "bill_to_country_code", "", 0}, {"Sales_Cr_Memo_Header", false, "sell_to_country_code", "", 0}, {"Sales_Cr_Memo_Header", false, "ship_to_country_code", "", 0}, {"Sales_Header", false, "vat_country_code", "", 0}, {"Sales_Header", false, "bill_to_country_code", "", 0}, {"Sales_Header", false, "sell_to_country_code", "", 0}, {"Sales_Header", false, "ship_to_country_code", "", 0}, {"Sales_Invoice_Header", false, "bill_to_country_code", "", 0}, {"Sales_Invoice_Header", false, "sell_to_country_code", "", 0}, {"Sales_Invoice_Header", false, "ship_to_country_code", "", 0}, {"Sales_Shipment_Header", false, "bill_to_country_code", "", 0}, {"Sales_Shipment_Header", false, "sell_to_country_code", "", 0}, {"Sales_Shipment_Header", false, "ship_to_country_code", "", 0}, {"Ship_to_Address", false, "country_code", "", 0}, {"Tax_Entry", false, "country_code", "", 0}, {"Vendor", false, "country_code", "", 0}, {"Vendor_Bank_Account", false, "country_code", "", 0}},
	}
	companies := []string{t.company}
	for _, ref := range references[field] {
		tables := []string{ref.table}
		if !ref.global {
			tables = tables[:0]
			for _, c := range companies {
				tables = append(tables, c+"$"+ref.table)
			}
		}
		for _, tbl := range tables {
			stmt := fmt.Sprintf(`UPDATE "%s" SET %s = ? WHERE %s = ?`, tbl, ref.column, ref.column)
			args := []interface{}{newValue, oldValue}
			if ref.condColumn != "" {
				stmt += fmt.Sprintf(" AND %s = ?", ref.condColumn)
				args = append(args, ref.condValue)
			}
			query := t.convertPlaceholders(stmt, len(args))
			if _, err := t.db.Exec(query, args...); err != nil {
				return fmt.Errorf("%s.%s: %w", tbl, ref.column, err)
			}
		}
	}
	return nil
}

